import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_FUNCION, MODELO_TEATRO, TABLA_FUNCIONES } from '../../models/teatro-funcion.model.mjs';

export async function buscarTeatroRepository(teatroId) {
  const { Item } = await MODELO_TEATRO.build(GetItemCommand)
    .key({ teatroId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarTeatroRepository(teatroId, minimo) {
  const { Items = [] } = await TABLA_FUNCIONES.build(QueryCommand)
    .entities(MODELO_FUNCION)
    .query({ index: 'PorTeatro', partition: teatroId })
    .options({ filters: { Funcion: { attr: 'aforo', gte: minimo } } })
    .send();
  return Items;
}
